def printed_offset(pages: dict[int, str]) -> int:
    """How far the journal's printed page numbers run ahead of the PDF's own count.

    Decks cite the page number printed on the paper, and the bridge numbers pages
    from 1. Paper 001 is paginated from 1, so the two agreed and nobody noticed; paper
    002 runs 620-629, so every cited page missed and 12 correct chart values came
    back WRONG_PAGE. Read from the paper: a page number sits alone on a line at the
    top or bottom of the page, so every such integer votes for (printed - pdf). The
    offset needs at least three pages and half the paper behind it, or it is 0 and
    nothing changes.
    """
    votes: dict[int, int] = {}
    for page, text in pages.items():
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        edges = lines[:3] + lines[-3:]
        offsets = {int(line) - page for line in edges
                   if line.isdigit() and int(line) >= page}
        for offset in offsets:
            votes[offset] = votes.get(offset, 0) + 1
    if not votes:
        return 0
    offset, support = max(votes.items(), key=lambda item: (item[1], -item[0]))
    return offset if support >= max(3, len(pages) / 2) else 0


def printed_pages(pages: dict[int, str]) -> dict[int, str]:
    """The same pages, keyed by the page number printed on them."""
    offset = printed_offset(pages)
    return {page + offset: text for page, text in pages.items()}


